#!/usr/bin/env python3
"""make_unit_v10.py L - writes uc_unitm<W>.v and uc_unitx<W>.v (ledger #1607): byte and halfword LOADS (lb lh lbu lhu) in a FUSED unit.
uc_unitm<W> = uc_unith<W> (left as proven) with the load decode of uc_core_v2w (lb lh lw lbu lhu legal, f3 011/110/111 trap) and two new outputs ld_nar = {unsigned, half, narrow} and ld_off = addr[1:0], valid with dmem_ld, as the core v2w gives them.
uc_unitx<W> = uc_unitw<W> (left as proven) around uc_unitm<W>: the word the unit reads its digit from is first cut down and extended (byte or halfword at the byte offset, sign or zero extended), so the digit select works at every width exactly as for lw; plus an output dmem_nar (a narrow load is live) for the pool's device-window check.
Needs uc_unith<W>.v and uc_unitw<W>.v (make_unit_v9.py).  Usage: python3 make_unit_v10.py 2 | 3 | 4 | 5"""
import os, re, subprocess, sys
L = int(sys.argv[1]); W = 1 << L; HERE = os.path.dirname(os.path.abspath(__file__))
h = open(os.path.join(HERE, 'uc_unith%d.v' % W)).read()
def rep(s, old, new):
    assert s.count(old) == 1, (old, s.count(old)); return s.replace(old, new)
h = rep(h, "    output wire              dmem_ld,        // ... and it is a load\n",
        "    output wire              dmem_ld,        // ... and it is a load\n    output wire [2:0]        ld_nar,         // v10: {unsigned, half, narrow} of a load: lb 001, lh 011, lbu 101, lhu 111, lw 000 (valid with dmem_ld)\n    output wire [1:0]        ld_off,         // v10: byte offset inside the word (addr[1:0]); a halfword uses bit 1 only\n")
h = rep(h, "    assign dmem_ld  = (state == S_WR2) & is_ld;\n",
        "    assign dmem_ld  = (state == S_WR2) & is_ld;\n    assign ld_nar   = {f3[2], f3[0] & ~f3[1], ~f3[1]};\n    assign ld_off   = addr[1:0];\n")
h = rep(h, "             | ((is_ld | is_st) & f3 != 3'b010)\n",
        "             | (is_st & f3 != 3'b010)\n             | (is_ld & (f3 == 3'b011 | f3 == 3'b110 | f3 == 3'b111))      // v10: lb lh lw lbu lhu are legal, the rest trap\n")
h = rep(h, 'module uc_unith%d #(' % W, 'module uc_unitm%d #(' % W)
h = '// uc_unitm%d.v (GENERATED by make_unit_v10.py %d from uc_unith%d.v, do not edit): the hooked unit with byte and halfword loads in the decode and the outputs ld_nar, ld_off (ledger #1607).\n' % (W, L, W) + h
open(os.path.join(HERE, 'uc_unitm%d.v' % W), 'w').write(h)
r = open(os.path.join(HERE, 'uc_unitw%d.v' % W)).read()
r = rep(r, "module uc_unitw%d (" % W, "module uc_unitx%d (" % W)
r = rep(r, "    output wire              dmem_ld,\n", "    output wire              dmem_ld,\n    output wire              dmem_nar,       // v10: the load live now is a byte or halfword load\n")
r = rep(r, "    uc_unith%d core (" % W, "    wire [2:0] ld_nar; wire [1:0] ld_off;\n    assign dmem_nar = ld_nar[0];\n    uc_unitm%d core (" % W)
r = rep(r, ".dmem_ld(dmem_ld),", ".dmem_ld(dmem_ld), .ld_nar(ld_nar), .ld_off(ld_off),")
# the widened word: byte or halfword at the offset, sign or zero extended, in front of the digit select
ext = ("    wire [7:0]  n_b   = ld_off[1] ? (ld_off[0] ? d_word[31:24] : d_word[23:16]) : (ld_off[0] ? d_word[15:8] : d_word[7:0]);\n"
       "    wire [15:0] n_h   = ld_off[1] ? d_word[31:16] : d_word[15:0];\n"
       "    wire [31:0] d_ext = !ld_nar[0] ? d_word : ld_nar[1] ? {{16{~ld_nar[2] & n_h[15]}}, n_h} : {{24{~ld_nar[2] & n_b[7]}}, n_b};\n")
r = rep(r, "    assign ra_wa = ra_addr[9:5];", ext + "    assign ra_wa = ra_addr[9:5];")
r = rep(r, ".w(d_word),  .kk(d_addr[4:0])", ".w(d_ext),   .kk(d_addr[4:0])")
r = re.sub(r'^// uc_unitw%d.v.*\n' % W, '// uc_unitx%d.v (GENERATED by make_unit_v10.py %d, do not edit): uc_unitw%d with byte and halfword loads (the loaded word is cut and extended before the digit select; ledger #1607).  Needs uc_unitm%d.v.\n' % (W, L, W, W), r, count=1)
open(os.path.join(HERE, 'uc_unitx%d.v' % W), 'w').write(r)
print('wrote uc_unitm%d.v and uc_unitx%d.v' % (W, W))
